-- Recipe Record: SAMBAL GORENG IKAN BILIS TRAVEL (ID: 2201)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2201, 'SAMBAL GORENG IKAN BILIS TRAVEL', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["20\u201330 tangkai cili kering (direbus dan ditoskan)","4 biji bawang besar","5 ulas bawang putih","Sedikit air"],"section":"Bahan Kisar"},{"items":["1 cawan ikan bilis (dibasuh dan ditoskan)","\u00bd cawan minyak masak (atau lebih sedikit)","Gula secukupnya","Garam secukupnya","1 sudu besar pes asam jawa + 3 sudu besar air","\u00bd sudu besar gula Melaka (pilihan, untuk rasa lebih lemak dan sedap)"],"section":"Bahan Lain"}]'::jsonb,
    '[{"items":["Kisar cili kering, bawang besar dan bawang putih dengan sedikit air sehingga halus.","Panaskan minyak secukupnya. Goreng ikan bilis sehingga garing. Angkat dan toskan. Ketepikan.","Dalam minyak yang sama, tumis bahan kisar dengan api sederhana kecil.","Kacau sekali-sekala. Nampak kering boleh masukkan air sedikit untuk garingkan sambal. Boleh ulang 3 kali sehingga sambal bertukar warna lebih gelap dan pecah minyak (20\u201330 minit).","Masukkan pes asam jawa, gula, gula melaka dan garam.","Kacau rata dan masak lagi sehingga sambal menjadi pekat. Rasa dan sesuaikan dengan citarasa.","Masukkan ikan bilis goreng dan gaul rata.","Masak lagi 5 minit supaya sambal menyerap ke dalam ikan bilis. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '["Jangan terlalu banyak bawang kerana sambal akan cepat berair.","Tumis lama sehingga benar-benar pecah minyak inilah kunci sambal yang sedap.","Gunakan campuran gula putih dan sedikit gula Melaka untuk rasa manis yang lebih seimbang.","Jika suka sambal lebih pedas, tambah 5\u201310 tangkai cili padi merah semasa mengisar."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-goreng-ikan-bilis-travel.webp', 'https://www.youtube.com/watch?v=G7PzeLRUdzE', 2201, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-goreng-ikan-bilis-travel.webp', 2201, 9.00, 'tier', 'pro', false
)
