INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2202, 'TELUR DADAR MASAK LEMAK CILI PADI', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1 biji bawang besar","5\u201310 biji cili padi (ikut citarasa)","2 inci kunyit hidup"],"section":"Bahan Kisar"},{"items":["4 biji telur","5-10 biji perahan limau kasturi","1-2 keping asam keping","1 helai daun kunyit (dimayang halus)","1 cawan santan/1 kotak santan (kecil)","1\u20131\u00bd cawan air","1 sudu kecil garam (atau secukup rasa)"],"section":"Bahan Lain"}]'::jsonb,
    '[{"items":["Buat telur dadar","Pecahkan telur ke dalam mangkuk dan pukul sebati.","Goreng menjadi telur dadar sehingga masak keemasan.","Angkat dan potong kepada beberapa bahagian. Ketepikan.","Sediakan kuah masak lemak","Kisar/tumbuk bawang besar, cili padi dan kunyit hidup bersama sedikit air hingga halus.","Masukkan bahan kisar ke dalam periuk bersama serai, asam keping, santan dan air.","Masak dengan api sederhana sambil sentiasa dikacau supaya santan tidak pecah.","Apabila kuah mula mendidih, masukkan garam secukup rasa.","Masukkan potongan telur dadar dan daun kunyit.","Biarkan mendidih perlahan selama 2\u20133 minit sehingga kuah sebati dan naik aroma daun kunyit.","Tutup api, dan masukkan perahan limau kasturi. Gaul sebati. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '["1 cawan santan pekat","1 cawan air Hidangkan panas-panas bersama nasi putih dan sambal belacan."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/telur-dadar-masak-lemak-cili-padi.webp', 'https://www.youtube.com/watch?v=St792WRrf-A', 2202, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/telur-dadar-masak-lemak-cili-padi.webp', 2202, 9.00, 'tier', 'pro', false
)
