-- Recipe Record: IKAN SIAKAP MASAK ASAM JAWA (ID: 2203)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2203, 'IKAN SIAKAP MASAK ASAM JAWA', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1 ekor ikan siakap, dibersihkan","1 sudu kecil serbuk kunyit","Sedikit garam","Minyak untuk menggoreng"],"section":"Bahan Ikan Goreng"},{"items":["4 ulas bawang putih, dihiris","5 biji bawang merah, dihiris","1 inci halia, dihiris halus","1 sudu kecil lada hitam (tumbuk-pilihan)","1 biji tomato (belah 4)","1 biji bawang Holland, dipotong wedges","5-10 biji cili padi (ikut tahap kepedasan)","Air asam jawa secukupnya","Garam secukup rasa","Gula secukup rasa","Sedikit perasa (jika suka)"],"section":"Bahan Lain"}]'::jsonb,
    '[{"items":["Lumurkan ikan siakap dengan serbuk kunyit dan sedikit garam hingga rata. Goreng sehingga masak dan keemasan. Angkat dan ketepikan.","Panaskan sedikit minyak. Tumis bawang putih, bawang merah, halia dan lada hitam sehingga naik bau dan sedikit garing.","Masukkan air asam jawa secukupnya. Kacau dan biarkan hingga mendidih.","Perasakan dengan garam, gula dan sedikit ajinomoto mengikut cita rasa. Seimbangkan rasa masam, manis dan masin.","Masukkan bawang Holland dan cili padi. Kacau sebentar sehingga bawang sedikit layu.","Akhir sekali, masukkan ikan siakap yang telah digoreng. Gaul perlahanlahan supaya kuah bersalut pada ikan.","Tutup api dan sedia untuk dihidangkan."],"section":"Cara Memasak"}]'::jsonb,
    '["Untuk rasa yang lebih segar dan aroma yang lebih wangi, boleh tabur daun ketumbar."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/ikan-siakap-masak-asam-jawa.webp', 'https://www.youtube.com/watch?v=GG__8YXsw-s', 2203, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/ikan-siakap-masak-asam-jawa.webp', 2203, 9.00, 'tier', 'pro', false
)
