INSERT INTO public.media_library (id, filename, hero_url, thumb_url, card_url, dominant_color, seo_schema, type) OVERRIDING SYSTEM VALUE 
VALUES (2204, 'bubur-lambuk-mudah.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/bubur-lambuk-mudah.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/bubur-lambuk-mudah.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/bubur-lambuk-mudah.webp', '#0A1517', 'BUBUR LAMBUK MUDAH', 'image')
