-- Recipe Record: BUBUR LAMBUK MUDAH (ID: 2204)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2204, 'BUBUR LAMBUK MUDAH', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["2 cawan beras","4.5 liter air (18 cawan)","200g daging (dipotong kecil)","2 sudu besar serbuk sup (kacau dengan 1/2 cawan air)","1 sudu kecil serbuk lada hitam","1 sudu kecil halba","\u00bd cawan santan pekat","60g lobak masin (dicincang halus-rendam 30minit)","Garam secukup rasa"],"section":"Bahan-Bahan"},{"items":["3 sudu besar minyak sapi","2 batang serai (dititik)","2 inci halia (dihiris)","6 biji bawang merah (dihiris)","2 ulas bawang putih (dihiris)","4 sekawan (2 kayu manis, 4 bunga lawang, 6 bunga cengkih, 6 buah pelaga)"],"section":"Bahan Tumis"},{"items":["Daun sup secukupnya","Daun bawang secukupnya","Bawang goreng secukupnya"],"section":"Bahan Tabur"}]'::jsonb,
    '[{"items":["Panaskan minyak sapi dalam periuk.","Masukkan rempah 4 sekawan. Tumis hingga naik bau.","Masukkan bawang merah, bawang putih, halia dan serai.","Tumis sehingga bawang layu dan wangi.","Masukkan bancuhan rempah sup. Tumis sehingga sedikit garing dan pecah minyak.","Kemudian, masukkan daging yang telah dipotong kecil.","Kacau dan masak sehingga daging bertukar warna dan kecut.","Masukkan beras yang telah dicuci bersih dan di tos airnya. Kacau rata supaya beras mesra dengan bahan tumisan.","Tuangkan 8 cawan air terlebih dahulu. Reneh sehingga beras kembang. Kacau selalu supaya tidak hangit. Masak dengan api perlahan. 10.Bila air semakin kering, tambah lagi 8 cawan air. Sambung reneh dengan api perlahan sehingga beras kembang. 11.Kemudian masukkan lada hitam, halba, lobak masin dan garam. Masukkan santan. Kacau sehingga semua bahan sebati. 12.Rasa dan sesuaikan dengan citarasa. Sambung reneh lebih kurang 15minit. Jika semakin kering, tambahkan sedikit air. Pastikan bubur tidak terlalu kering dan tidak terlalu cair. 13.Kacau rata dan biarkan mendidih. 14.Akhir sekali, tabur daun bawang, daun sup dan bawang goreng. 15.Siap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/bubur-lambuk-mudah.webp', 'https://www.youtube.com/watch?v=r0DMwI8up8w', 2204, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/bubur-lambuk-mudah.webp', 2204, 9.00, 'tier', 'pro', false
)
