-- Recipe Record: RICE PAPER LADNA SEAFOOD (ID: 2205)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2205, 'RICE PAPER LADNA SEAFOOD', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["3 sudu besar minyak masak","3 ulas bawang putih (dicincang halus)","10 ekor udang (dikupas dan dibuang urat hitam) / boleh ganti tauhu","3 ekor sotong","1/4 Kobis bunga (secukupnya)","1/2 batang lobak merah (dihiris nipis)","1 biji tomato (belah 6)","1 sudu besar sos tiram","1 kiub pati ayam","1/2 sudu besar serbuk lada sulah","4 cawan air","Garam secukup rasa","3 sudu besar air bancuhan tepung jagung Sawi/pak coy (dipotong)","1 biji telur (dipukul) Daun bawang (dihiris)"],"section":"Bahan Kuah"},{"items":["5 keping rice paper","1 biji telur"],"section":"1 Biji Limau Nipis (Untuk Hidang) Bahan Special (Rice Paper)"},{"items":["5 Tangkai Cili padi (dipotong)","2 biji limau kasturi","Kicap cair dan manis secukupnya"],"section":"Bahan Cili Kicap"}]'::jsonb,
    '[{"items":["Kuah ladna","Panaskan minyak dalam kuali, kemudian tumis bawang putih sehingga kekuningan dan naik bau.","Masukkan udang dan kacau sehingga separuh masak. Keluarkan.","Masukkan lobak merah, batang sawi, kobis bunga. Kacau rata.","Tambahkan sos tiram, air dan kiub pati ayam. Biarkan sehingga kuah mendidih.","Masukkan serbuk lada sulah dan garam secukup rasa.","Tuangkan air bancuhan tepung jagung sedikit demi sedikit sambil dikacau sehingga kuah pekat ikut citarasa.","Masukkan sotong, daun sawi dan tomato masak sebentar sehingga sotong masak dan sayur layu.","Tuangkan telur yang telah dipukul secara perlahan-lahan mengelilingi kuali untuk menghasilkan telur berjurai. masukkan udang. biar mendidih seketika.","Tutup api dan taburkan daun bawang.","Special Rice Paper (Mee)","Gunting rice paper kepada jalur-jalur nipis mengikut saiz kuey teow.","Pecahkan telur ke dalam mangkuk dan pukul sehingga sebati.","Masukkan rice paper yang telah digunting ke dalam telur dan gaul rata sehingga semua rice paper bersalut telur.","Panaskan minyak secukupnya dalam kuali.","Goreng rice paper bersalut telur sehingga keemasan dan rangup.","Angkat dan toskan minyak berlebihan.","Letakkan di dalam mangkuk atau pinggan dan siram dengan kuah seafood yang panas.","Kicap Pedas","Potong cili padi mengikut citarasa.","Masukkan kicap manis secukupnya.","Perahkan limau kasturi dan gaul sebati."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/rice-paper-ladna-seafood.webp', 'https://www.youtube.com/watch?v=d9xfMA6QV-A', 2205, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/rice-paper-ladna-seafood.webp', 2205, 9.00, 'tier', 'pro', false
)
