INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2207, 'POPIA SAYUR MUDAH', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["kulit popia secukupnya","\u00bd biji kubis (dihiris halus)","1 batang lobak merah (diparut atau dihiris halus)","1 genggam taugeh","1 biji bawang Holland/bawang merah (dihiris nipis)","3 ulas bawang putih (dicincang halus)","1-2 sudu kecil perasa (atau secukup rasa)","Sedikit serbuk lada sulah","1-2 biji cili merah/hijau (dihiris) (pilihan)","Sedikit air atau bancuhan tepung gandum untuk melekatkan kulit popia","Minyak untuk menggoreng"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Sediakan Inti","Panaskan sedikit minyak di dalam kuali.","Tumis bawang putih dan bawang Holland sehingga naik bau dan layu.","Masukkan lobak merah, kacau selama 1-2 minit.","Masukkan taugeh dan kubis, kemudian gaul rata.","Perasakan dengan perasa dan sedikit serbuk lada sulah.","Masukkan hirisan cili jika suka.","Kacau sehingga sayur layu sedikit tetapi masih rangup.","Tutup api dan sejukkan inti sepenuhnya sebelum dibungkus."],"section":"Cara Memasak"}]'::jsonb,
    '["kekal rangup.","Membungkus Popia","Ambil sekeping kulit popia.","Letakkan secukupnya inti di bahagian bawah kulit.","Lipat kedua-dua sisi ke dalam.","Gulung dengan kemas.","Sapukan sedikit air atau bancuhan tepung gandum di hujung kulit untuk melekatkan gulungan.","Ulang sehingga semua inti habis.","Menggoreng","Panaskan minyak dengan api sederhana.","Goreng popia sehingga bertukar warna perang keemasan dan rangup.","Angkat dan toskan minyak.","Sedia dihidangkan bersama sos cili atau sos Thai. Tips Anti Gagal","Pastikan inti betul-betul sejuk sebelum membungkus.","Jangan letak inti terlalu banyak supaya popia tidak pecah.","Goreng menggunakan api sederhana agar kulit masak sekata dan kekal rangup.","Jika ingin disimpan sejuk beku, susun popia dalam bekas berlapik plastik supaya tidak melekat antara satu sama lain."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/popia-sayur-mudah.webp', 'https://www.youtube.com/watch?v=6DCYYYRJBmE', 2207, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/popia-sayur-mudah.webp', 2207, 9.00, 'tier', 'pro', false
)
