VALUES (
    2209, 'CUCUR SAYUR RANGUP', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["150g kubis (dihiris halus)","\u00bd batang lobak merah (diparut)","1 biji cili merah/hijau (dihiris nipis) - boleh diabaikan. Jika tidak menggunakan","cili, tambah \u00bd sudu kecil serbuk lada putih ke dalam bancuhan tepung.","10-15 batang kucai (dipotong kasar)","100g taugeh","\u00bd biji bawang Holland (dicincang)","3 ulas bawang putih (dicincang halus)","Minyak secukupnya untuk menggoreng"],"section":"Bahan"},{"items":["1\u00bd cawan tepung gandum","1 sudu kecil tepung jagung","\u00bd sudu kecil serbuk penaik (baking powder)","1 sudu kecil serbuk kunyit","1 sudu kecil garam","1 cawan air (suhu bilik sahaja- kalau cuaca sangat panas guna air sejuk)"],"section":"Bancuhan Tepung"}]'::jsonb,
    '[{"items":["Satukan semua bahan bancuhan tepung di dalam mangkuk. Kacau sehingga menjadi adunan yang licin dan tidak berketul.","Masukkan kubis, lobak merah, cili, kucai, taugeh, bawang Holland, bawang putih dan bawang goreng (jika menggunakan).","Gaul sehingga semua sayur bersalut rata dengan adunan tepung.","Panaskan minyak dengan api sederhana.","Cedok satu sudu adunan dan perlahan-lahan masukkan ke dalam minyak panas.","Goreng sehingga kedua-dua belah cucur berwarna kuning keemasan dan rangup.","Angkat dan toskan minyak sebelum dihidangkan. Tips","Jangan bancuh adunan terlalu cair supaya cucur lebih rangup.","Gunakan minyak yang benar-benar panas sebelum mula menggoreng.","Goreng menggunakan api sederhana supaya cucur masak sekata tanpa cepat hangus.","Paling sedap dimakan panas-panas bersama sos Cicah homemade atau sambal kicap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cucur-sayur-rangup.webp', 'https://www.youtube.com/watch?v=6TObXY8c_hg', 2209, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cucur-sayur-rangup.webp', 2209, 9.00, 'tier', 'pro', false
)
