-- Recipe Record: GULAI NASI BERLAUK IKAN TONGKOL (ID: 2210)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2210, 'GULAI NASI BERLAUK IKAN TONGKOL', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1 ekor ikan tongkol","2-3 keping asam keping (ikut citarasa)","5 sudu besar minyak masak","500\u2013800 ml santan pekat","1 biji timun (buang biji, belah memanjang dan potong)","4 tangkai kacang panjang (potong 2\u20133 inci)","5 tangkai cili padi merah","5 biji telur rebus (dikupas)","Garam secukup rasa","Gula secukup rasa","Air secukupnya"],"section":"Bahan"},{"items":["3 biji bawang merah besar","6 ulas bawang putih","5-10 tangkai cili kering (ikut tahap kepedasan)","2 inci kunyit hidup","1 inci halia","1\u00bd inci lengkuas","3 biji cili hidup merah","10\u201315 biji cili padi (ikut tahap kepedasan)"],"section":"Bahan Kisar"}]'::jsonb,
    '[{"items":["Bersihkan ikan tongkol dan potong mengikut saiz yang dikehendaki.","Masukkan ikan ke dalam kuali bersama: \u25e6 2 keping asam keping \u25e6 Sedikit garam \u25e6 Sedikit air (sekadar menutup dasar kuali) tak perlu sampai ikan tenggelam.","Masak dengan api sederhana perlahan sehingga ikan mengeluarkan air dan masak. Angkat dan ketepikan bersama air rebusannya.","Panaskan minyak. Masukkan bahan kisar dan tumis lagi sehingga betul-betul garing, wangi dan naik minyak.","Tuangkan santan sedikit demi sedikit sambil dikacau supaya santan tidak pecah.","Masukkan air rebusan ikan bersama ikan tongkol. Masuk sekali asam keping. Reneh sehingga minyak mula naik.","Perasakan dengan garam dan sedikit gula mengikut cita rasa.","Masukkan timun, kacang panjang dan cili padi merah.","Reneh sehingga sayur hampir empuk.","Akhir sekali, masukkan telur rebus dan biarkan gulai mereneh selama 3\u20135 minit supaya telur menyerap kuah.","Tutup api dan sedia dihidangkan bersama nasi putih dan sambal belacan. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/gulai-nasi-berlauk-ikan-tongkol.webp', 'https://www.youtube.com/watch?v=5W3qnjy5bdk', 2210, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/gulai-nasi-berlauk-ikan-tongkol.webp', 2210, 9.00, 'tier', 'pro', false
)
