    '[{"items":["1 ekor ayam (dipotong sederhana)","Garam secukupnya","Serbuk kunyit secukupnya"],"section":"Bahan"},{"items":["15-20 tangkai cili kering (direbus/rendam hingga lembut)","3 biji bawang merah/ 1 biji bawang besar","4 ulas bawang putih","1 inci halia"],"section":"Bahan Kisar"},{"items":["2 batang serai (dititik)","3 helai daun limau purut","1/ 2 sudu besar pes asam jawa (bancuh dengan air)","Kicap lemak manis secukupnya","Garam secukupnya","Gula secukupnya","1 biji limau nipis (ambil jus- boleh sesuaikan ikut citarasa)","Cili padi hijau/merah secukupnya"],"section":"Bahan Lain"}]'::jsonb,
    '[{"items":["Rebus/rendam cili kering sehingga lembut, kemudian toskan.","Kisar cili kering bersama bawang merah, bawang putih dan halia bersama sedikit air hingga halus.","Gaulkan ayam dengan garam dan serbuk kunyit. Goreng sehingga masak dan keperangan. Angkat dan ketepikan.","Panaskan minyak, lebihkan sedikit dan tumis bahan kisar hingga pecah minyak.","Masukkan serai dan daun limau purut. Tumis lagi hingga harum.","Bancuh pes asam jawa dengan 2\u20133 sudu besar air. Seterusnya masukkan ke dalam bahan tumis.","Kemudian, masukkan kicap lemak manis mengikut citarasa, kemudian perasakan dengan garam dan gula.","Masukkan ayam goreng dan gaul hingga sambal bersalut rata pada ayam.","Masukkan cili padi, gaul sebentar.","Tutup api, kemudian perahkan jus limau nipis. Gaul rata dan sedia untuk dihidangkan."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-ayam-kicap.webp', 'https://www.youtube.com/watch?v=ACpNIF1-UiI', 2212, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-ayam-kicap.webp', 2212, 9.00, 'tier', 'pro', false
)
