INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2213, 'KOBIS GORENG TELUR UDANG', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1/2 biji kubis (dihiris halus)","10 ekor udang sederhana (dibuang kulit dan dibersihkan)","2 biji telur","3 ulas bawang putih (dicincang)","1 biji bawang merah (dihiris)","1 biji cili merah (dihiris) \u2013 pilihan","1 sudu kecil sos tiram","1/2 sudu kecil lada sulah","1/2 sudu kecil garam (atau secukup rasa)","1/2 sudu kecil serbuk perasa (pilihan)","3 sudu makan minyak masak"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Panaskan minyak, kemudian tumis bawang putih dan bawang merah sehingga naik bau. Biar garing sedikit.","Masukkan udang dan masak sehingga bertukar warna kemerahmerahan.","Masukkan kubis dan sedikit air goreng selama 2\u20133 minit sehingga sedikit layu tetapi masih rangup.","Masukkan sos tiram, garam, lada sulah dan serbuk perasa. Gaul rata.","Tolakkan kubis ke tepi kuali, kemudian pecahkan telur. Biarkan seketika sebelum dikacau sehingga menjadi telur hancur.","Gaulkan telur bersama kubis dan udang hingga sebati.","Angkat dan hidangkan panas."],"section":"Cara Memasak"}]'::jsonb,
    '["keras. Cukup sehingga bertukar warna sahaja."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/kobis-goreng-telur-udang.webp', 'https://www.youtube.com/watch?v=ACpNIF1-UiI', 2213, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/kobis-goreng-telur-udang.webp', 2213, 9.00, 'tier', 'pro', false
)
