-- Recipe Record: GOLDEN FRIED RICE (ID: 2214)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2214, 'GOLDEN FRIED RICE', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["3 biji telur Omega","400gm nasi putih yang telah masak (sejuk lebih baik)","3 ulas bawang putih (dicincang halus)","2 batang daun bawang sederhana (dihiris)","\u00bd cawan jagung manis (Jika suka)","1 sudu besar kicap masin","\u00bd sudu kecil sos ikan","\u00bc sudu kecil garam","2 sudu kecil gula","\u00bd sudu kecil serbuk perasa / pati ayam","\u00bc sudu kecil serbuk lada sulah","Minyak secukupnya untuk menumis"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Cincang bawang putih, hiris daun bawang (asingkan bahagian putih dan hijau), Ketepikan.","Asingkan kuning telur dan putih telur. Campurkan nasi bersama kuning telur sehingga setiap butir nasi disaluti rata.","Panaskan sedikit minyak di dalam kuali. Masukkan putih telur dan kacau hingga berderai.","Masukkan bawang putih serta bahagian putih daun bawang. Tumis hingga naik bau.","Masukkan nasi yang telah disaluti kuning telur. Goreng sambil dikacau sehingga rata.","Tambahkan kicap masin dan sos ikan. Gaul hingga sebati.","Masukkan gula, lada sulah, garam dan serbuk perasa. Kacau sehingga semua bahan sebati.","Akhir sekali, masukkan jagung dan bahagian hijau daun bawang. Gaul selama 1\u20132 minit sehingga jagung masak dan daun bawang layu sedikit.","Angkat dan hidangkan ketika masih panas."],"section":"Cara Memasak"}]'::jsonb,
    '["Gunakan nasi yang telah disejukkan semalaman untuk hasil nasi goreng yang lebih berderai.","Menyalut nasi dengan kuning telur sebelum digoreng menghasilkan warna keemasan yang cantik dan tekstur yang lebih wangi serta gebu.","Boleh tambah isi ayam, udang atau daging jika mahu dijadikan hidangan yang lebih lengkap."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/golden-fried-rice.webp', 'https://www.youtube.com/watch?v=uwJtEuiKRdM', 2214, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/golden-fried-rice.webp', 2214, 9.00, 'tier', 'pro', false
)
