    2215, 'ICED CHURRO BUTTER LATTE (16OZ)', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["2 sudu kecil instant co ee","30ml air panas","15\u201320g gula perang/ karamel/madu (\u00bd sudu besar)","5\u20138g unsalted butter (lebih kurang 1\u20131\u00bd sudu kecil)","1 sudu besar susu pekat","Secubit garam","180\u2013200ml susu segar","Ais secukupnya","Serbuk kayu manis / serbuk koko secukupnya"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Masukkan instant co ee dengan air panas.","Masukkan gula perang, garam susu pekat dan unsalted butter.","Kacau sehingga semua bahan sebati sepenuhnya. Jika ada milk frother atau blender, kisar 20-30 saat untuk menghasilkan tekstur yang lebih halus dan berkrim.","Isi gelas dengan ais dan susu segar. ff ff","Taburkan sedikit serbuk kayu manis atau koko. Tip Penting","Gunakan 5g butter jika mahu rasa ringan.","Gunakan 8g butter jika mahukan rasa lebih kaya seperti butter co ee.","Jangan letak terlalu banyak (lebih 10g), kerana butter boleh terapung dan membuat minuman terasa berminyak apabila sejuk.","Sedikit ekstrak vanila (\u00bc sudu kecil) atau sos karamel (5\u201310ml) juga ff fi sangat sesuai untuk melengkapkan pro l rasa churro."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/iced-churro-butter-latte-16oz.webp', 'https://www.youtube.com/watch?v=uwJtEuiKRdM', 2215, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/iced-churro-butter-latte-16oz.webp', 2215, 9.00, 'tier', 'pro', false
)
