-- Recipe Record: Classic Crepe (ID: 2216)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2216, 'Classic Crepe', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["3 biji telur (gred A/B)","120g tepung gandum","180ml susu penuh krim (full cream milk)","120ml air"],"section":"Bahan"},{"items":["sudu kecil esen vanila (pilihan)","sudu kecil garam (secubit)"],"section":"1 Sudu Besar Mentega Tanpa Garam, Dicairkan (Tambahan Sedikit Mentega Untuk Sapuan Pada Kuali)"}]'::jsonb,
    '[{"items":["Masukkan telur, tepung gandum, susu, air, mentega cair, esen vanila dan garam ke dalam mangkuk atau blender.","Pukul menggunakan whisk sehingga adunan licin tanpa berketul, atau kisar selama kira-kira 30 saat.","Tutup mangkuk dan simpan adunan di dalam peti sejuk sekurang-kurangnya 30minit. (boleh disimpan sehingga 4 jam). Langkah ini membantu menghasilkan crepe yang lebih lembut dan tidak mudah koyak.","Panaskan kuali non-stick 8 inci dengan api sederhana. Sapu sedikit mentega pada permukaan kuali.","Tuangkan 3 sudu besar adunan ke dalam kuali, kemudian segera pusingkan kuali supaya adunan meliputi keseluruhan dasar dengan nipis dan sekata.","Masak selama 30-45 saat atau sehingga bahagian bawah bertukar perang keemasan.","Terbalikkan crepe dan masak lagi selama 10-15 saat.","Angkat dan susun di atas pinggan. Tutup dengan kain bersih supaya crepe kekal lembut dan suam.","Ulang sehingga semua adunan habis. Sapu sedikit mentega pada kuali jika perlu sebelum memasak crepe seterusnya."],"section":"Cara Memasak"}]'::jsonb,
    '["Cadangan Inti/Topping: Nutella, Buah-buahan segar (strawberi, pisang, kiwi atau beri), Whipping cream, Gula aising, Jem buah, Peanut butter, Lotus Biscoff spread","Jika adunan terlalu pekat selepas disejukkan, tambahkan 1-2 sudu besar air atau susu dan kacau sehingga mencapai konsistensi yang sesuai.","Pastikan kuali benar-benar panas sebelum menuang adunan pertama.","Tuang adunan nipis untuk mendapatkan crepe yang lembut dan elastik.","Crepe yang telah dimasak boleh disimpan di dalam peti sejuk selama 2-3 hari dengan meletakkan baking paper di antara setiap keping."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/classic-crepe.webp', 'https://www.youtube.com/watch?v=w6lBZYaPVjU', 2216, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/classic-crepe.webp', 2216, 9.00, 'tier', 'pro', false
)
