-- Recipe Record: EASY Chocolate Drizzle (ID: 2218)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2218, 'EASY Chocolate Drizzle', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["100g coklat masakan (dark, milk atau semi-sweet)","50ml whipping cream (atau 2-3 sudu besar susu penuh krim)","10g mentega tanpa garam (pilihan, untuk nampak berkilat)"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Panaskan whipping cream atau susu sehingga hampir mendidih (jangan sampai menggelegak).","Tuangkan ke atas coklat yang telah dicincang.","Biarkan selama 1 minit.","Kacau sehingga coklat cair dan licin.","Masukkan mentega dan kacau hingga sebati.","Biarkan suam sedikit sebelum direnjis (drizzle) ke atas crepe."],"section":"Cara Memasak"}]'::jsonb,
    '["Jika terlalu pekat: Tambah sedikit susu panas.","Jika terlalu cair: Tambah sedikit coklat cincang dan kacau hingga larut."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/easy-chocolate-drizzle.webp', 'https://www.youtube.com/watch?v=w6lBZYaPVjU', 2218, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/easy-chocolate-drizzle.webp', 2218, 9.00, 'tier', 'pro', false
)
