-- Recipe Record: Cheesy Garlic Bread (ID: 2219)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2219, 'Cheesy Garlic Bread', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["260g tepung gandum/protein tinggi (High Protein/Bread Flour)","160ml susu segar suam (sekitar 35C)","1 sudu kecil yis segera (Instant Yeast)","20g gula (lebih kurang 1 sudu besar)","30ml minyak olive/minyak masak (2 sudu besar)"],"section":"Bahan Doh"},{"items":["30g mentega tanpa garam (Unsalted Butter), di lembutkan","2 sudu kecil bawang putih parut halus (3 ulas bawang putih)","2 sudu kecil daun parsley atau mixed herbs cincang halus","180g keju mozzarella, dipotong blok"],"section":"Bahan Garlic Butter"}]'::jsonb,
    '[{"items":["1. Sediakan Doh: Masukkan susu suam, gula dan yis ke dalam mangkuk. Kacau sebati.","Masukkan minyak, garam dan tepung gandum. Gaul sehingga menjadi doh kasar.","Uli selama 10-12 minit secara manual sehingga doh licin, lembut dan anjal. Jika menggunakan stand mixer, uli menggunakan dough hook selama 8 minit.","Rehatkan doh selama 15 minit dan tutup dengan kain atau plastik.","2. Bentukkan Doh: Guna loyang petak 10 x 10 x 2 inch. Canai doh menjadi bentuk segi empat tepat setebal lebih kurang 1.5-2cm atau mengikut size loyang.","Letakkan di atas loyang yang dialas baking paper.","Gunakan pisau tajam untuk membuat corak silang (criss-cross) pada permukaan doh tanpa memotong hingga putus.","3. Sediakan Garlic Butter: Campurkan mentega lembut, bawang putih cincang, parsley atau mixed herbs.","Sapu rata campuran garlic butter pada permukaan doh sehingga masuk ke dalam setiap potongan.","4. Letakkan Keju: Selitkan atau isikan potongan keju mozzarella ke dalam setiap celahan potongan doh.","5. Proofing: Tutup loyang menggunakan plastik atau kain bersih. Biarkan doh naik selama 30 minit, atau sehingga saiznya menjadi hampir dua kali ganda.","6. Bakar: Panaskan oven terlebih dahulu selama 15 minit.","Bakar pada suhu 180C (api atas bawah) selama 28-35 minit."],"section":"Cara Memasak"}]'::jsonb,
    '["Loyang yang lebih dalam memerlukan masa membakar yang sedikit lebih lama. Jadi pantau masa membakar.","Jika permukaan cepat perang sebelum masak sepenuhnya, tutup dengan aluminium foil dan teruskan membakar sehingga siap.","Gunakan tepung roti (High Protein/Bread Flour) untuk tekstur yang lebih lembut dan gebu.","Pastikan susu hanya suam (sekitar 35C), bukan panas, supaya yis kekal aktif.","Keju mozzarella blok yang dipotong memanjang memberikan efek cheese pull yang lebih cantik berbanding keju parut.","Garlic bread paling sedap dinikmati ketika masih panas kerana kejunya masih cair dan memanjang."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cheesy-garlic-bread.webp', 'https://www.youtube.com/watch?v=C-QOxlTSmSY', 2219, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cheesy-garlic-bread.webp', 2219, 9.00, 'tier', 'pro', false
)
