-- Recipe Record: Ikan Masak Asam Ala Thai (ID: 2220)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2220, 'Ikan Masak Asam Ala Thai', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1 ekor ikan tenggiri/siakap/merah etc (dipotong 4-5 bahagian)","3 sudu besar tepung jagung","8-10 ulas bawang putih","5-10 biji cili padi merah (ikut tahap kepedasan)","2 biji cili hidup merah","4 tangkai cili kering (cuci dan keringkan)","5 tangkai daun ketumbar (asingkan batang dan daun)","6 sudu besar sos ikan","1-2 sudu besar pes asam jawa (dibancuh dengan 3-4 sudu besar air, tapis)","1 sudu besar gula (Thai Palm Sugar)","1 sudu kecil serbuk lada sulah","sebuk kunyit","300-400 ml air","Garam secukup rasa (jika perlu)","Minyak untuk menggoreng dan menumis"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Bersihkan ikan tenggiri dan lap/tos sehingga kering.","Perasakan dengan sedikit garam, kunyit dan serbuk lada sulah (pilihan).","Salut nipis ikan dengan 3 sudu besar tepung jagung sehingga rata. Tepuk lebihan tepung.","Goreng ikan selama 4-6 minit setiap bahagian (bergantung pada ketebalan ikan) sehingga berwarna keemasan dan garing.","Angkat dan toskan di atas rak atau tisu dapur.","Tumbuk cili padi merah, cili merah, bawang putih dan batang ketumbar. Tidak perlu terlalu halus, biarkan teksturnya sedikit kasar.","Panaskan sedikit minyak, kemudian tumis bahan tumbuk sehingga naik bau dan sedikit garing.","Masukkan cili kering yang dipotong kasar. Tumis seketika sahaja sehingga wangi, jangan tumis terlalu lama atau sehingga garing supaya warna dan rasanya kekal cantik tidak pahit.","Tuangkan air secukupnya biarkan mendidih seketika.","Kemudian masukkan pes asam jawa yang telah di bancuh dengan air. Kacau sehingga sebati dan biarkan kuah mendidih.","Masukkan sos ikan, gula thai kemudian kacau sehingga gula larut.","Rasa kuah dan sesuaikan masam, masin atau manis mengikut cita rasa.","Tutup api, dan biarkan kuah suam seketika baru tuang di atas ikan.","Tabur daun ketumbar. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/ikan-masak-asam-ala-thai.webp', 'https://www.youtube.com/watch?v=AgytsdmZWtQ', 2220, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/ikan-masak-asam-ala-thai.webp', 2220, 9.00, 'tier', 'pro', false
)
