    '[{"items":["2 sudu kecil kopi segera (instant coffee)","1 sudu makan gula perang","35 ml air panas"],"section":"Bahan Dalgona"},{"items":["200 ml susu segar full cream","Ais secukupnya"],"section":"Base Minuman"},{"items":["1-2 scoop aiskrim vanila"],"section":"Bahan Topping"}]'::jsonb,
