INSERT INTO public.media_library (id, filename, hero_url, thumb_url, card_url, dominant_color, seo_schema, type) OVERRIDING SYSTEM VALUE 
VALUES (2222, 'cempedak-goreng-2.0.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cempedak-goreng-2.0.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cempedak-goreng-2.0.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cempedak-goreng-2.0.webp', '#0A1517', 'Cempedak Goreng 2.0', 'image')
