-- Recipe Record: Cempedak Goreng 2.0 (ID: 2222)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2222, 'Cempedak Goreng 2.0', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["Isi cempedak secukupnya","2 cawan tepung beras (Cap Tiga Gajah)","5 sudu besar tepung jagung","1 cawan air ais / air sejuk","1 sudu besar gula","1 sudu kecil garam halus","1 biji kuning telur sahaja","1 sudu besar air kapur (yang jernih sahaja)","Sedikit pewarna kuning/serbuk kunyit (pilihan)","Minyak masak secukupnya"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Satukan tepung beras, tepung jagung, gula dan garam di dalam mangkuk.","Masukkan kuning telur, air kapur jernih dan sedikit pewarna kuning telur atau serbuk kunyit jika digunakan.","Tuangkan air ais sedikit demi sedikit sambil dikacau sehingga menjadi adunan yang licin dan tidak berketul. Bancuhan tidak terlalu cair dan tidak terlalu pekat.","Biarkan adunan berehat selama 10-15 minit sebelum digunakan.","Celup isi cempedak ke dalam adunan sehingga bersalut rata.","Goreng dalam minyak yang telah dipanaskan pada api sederhana sehingga keemasan dan rangup. Angkat dan toskan sebelum dihidangkan."],"section":"Cara Memasak"}]'::jsonb,
    '["Gunakan air yang benar-benar sejuk atau berais untuk membantu menghasilkan salutan yang lebih rangup.","Jangan bancuh adunan terlalu cair, salutan perlu melekat elok pada isi cempedak.","Goreng dalam minyak yang banyak dan betul-betul panas (sekitar 170C).","Elakkan menggoreng terlalu banyak dalam satu masa supaya suhu minyak kekal stabil dan cempedak lebih rangup.","Kelebihan menggunakan kuning telur sahaja: Salutan lebih rangup, Kurang menyerap minyak, Warna lebih cantik, Tekstur lebih ringan."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cempedak-goreng-2.0.webp', 'https://www.youtube.com/watch?v=A5moqbksbwM', 2222, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/cempedak-goreng-2.0.webp', 2222, 9.00, 'tier', 'pro', false
)
