-- Recipe Record: Sambal Tumis Udang Petai (ID: 2223)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2223, 'Sambal Tumis Udang Petai', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["15 ekor udang saiz besar","1/2 mangkuk isi petai (ikut citarasa)","1 biji bawang besar (dihiris nipis untuk ditumis)","1 biji bawang besar dipotong bulat (dimasukkan di akhir masakan)","2 sudu besar pes asam jawa, bancuh dengan 3 sudu besar air","1-2 sudu besar gula Melaka (secukup rasa)","1 sudu kecil serbuk perasa (pilihan)","cawan minyak masak (secukupnya)","2 biji bawang merah besar","15-20 tangkai cili kering (direbus/rendam lembut dan ditoskan)"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Bersihkan udang dengan membuang urat hitam di belakang. Gaulkan dengan sedikit garam dan ketepikan.","Kisar halus bawang merah besar, bawang putih (jika ada) dan cili kering.","Panaskan sedikit minyak, kemudian goreng udang selama 30-60 saat sehingga separuh masak. Angkat dan ketepikan.","Tambah minyak jika perlu. Tumis bawang besar yang dihiris sehingga layu dan kekuningan.","Masukkan bahan kisar dan tumis sehingga pecah minyak serta cili benar-benar masak. Sepanjang proses ini, masukkan sedikit air 2-3 kali supaya cili garing pecah minyak dan masak sempurna.","Masukkan pes asam jawa, gula Melaka, serbuk perasa dan garam secukup rasa. Masak sehingga sambal pekat dan berkilat. Rasa dan sesuaikam dengan citarasa.","Masukkan semula udang dan petai, kemudian masukkan bawang besar yang dipotong bulat.","Gaul rata selama 1-2 minit sehingga semua bahan bersalut sambal dan bawang sedikit layu. Tutup api dan sedia dihidangkan."],"section":"Cara Memasak"}]'::jsonb,
    '["Lebihkan bawang besar untuk menghasilkan sambal yang lebih manis secara semula jadi.","Asam jawa memberikan rasa masam yang seimbang dan menjadikan sambal lebih membuka selera.","Jangan masak udang terlalu lama supaya isinya kekal lembut dan manis."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-tumis-udang-petai.webp', '', 2223, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/sambal-tumis-udang-petai.webp', 2223, 9.00, 'tier', 'pro', false
)
