-- Recipe Record: Nasi Lemak Sempoi (ID: 2224)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2224, 'Nasi Lemak Sempoi', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["4 cawan beras basmathi","2 cawan santan","2 sudu besar minyak masak","2 helai daun pandan (disimpul)","1 inci halia (dihiris nipis)","Garam secukup rasa","Air secukupnya"],"section":"Bahan"},{"items":["Timun (dihiris)","Telur rebus"],"section":"Bahan Sampingan"}]'::jsonb,
    '[{"items":["Basuh beras basmathi 2-3 kali sehingga air hampir jernih.","Rendam beras selama 20 minit, kemudian toskan.","Masukkan beras ke dalam periuk nasi bersama air, santan, minyak masak, halia, daun pandan dan garam.","Kacau rata dan masak seperti biasa.","Setelah nasi masak, biarkan dalam keadaan warm selama 10 minit.","Gemburkan nasi perlahan-lahan sebelum dihidangkan. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '["Jika guna beras biasa nisbah beras:air (1:1.5)"]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/nasi-lemak-sempoi.webp', '', 2224, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/nasi-lemak-sempoi.webp', 2224, 9.00, 'tier', 'pro', false
)
