-- Recipe Record: Nasi Goreng Daging (Mongolian Style) (ID: 2225)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2225, 'Nasi Goreng Daging (Mongolian Style)', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["300g daging (hiris nipis)","1 sudu besar kicap cair","2 sudu besar tepung jagung","sudu kecil lada hitam","1 sudu besar baking soda"],"section":"Bahan Perap Daging"},{"items":["2 mangkuk nasi sejuk (500g-600g)","300g daging perap","8 ulas bawang putih (cincang halus)","1 biji bawang besar (hiris)","3 tangkai daun bawang","1/2 batang lobak merah (potong kiub)","2-3 tangkai cili merah (hiris serong)","8-10 biji cili padi (hiris, ikut tahap pedas)","Sedikit minyak"],"section":"Bahan Utama"},{"items":["2 sudu besar kicap cair","1 sudu besar kicap pekat (sekadar beri warna, bukan untuk manis)","1 sudu kecil sos ikan","sudu kecil lada hitam (tumbuk)","1 sudu kecil serbuk lada sulah","sudu kecil gula perang","1 sudu kecil minyak bijan (jika suka)","2-3 sudu besar air (Secukupnya)"],"section":"Bahan Sos"}]'::jsonb,
    '[{"items":["Perap daging dengan baking soda selama 10 minit. Jangan terlebih masa nanti boleh jadi pahit. Daging jadi terlalu lembut dan lembik. Bilas seketika. Kemudian toskan.","Gaul daging bersama bahan perasa dan panaskan minyak secukupnya untuk menggoreng daging.","Goreng daging hingga sedikit garing anggaran 3-4minit. Angkat dan ketepikan.","Tumis bawang putih hingga keemasan.","Masukkan bawang besar, cili merah dan cili padi. Tumis hingga wangi.","Masukkan semua bahan sos dan biarkan mendidih seketika.","Masukkan lobak merah, biar sedikit lembut.","Masukkan nasi sejuk dan gaul hingga rata.","Masukkan semula daging dan daun bawang. Gaul dengan api besar selama 2-3 minit.","Titiskan sedikit minyak bijan jika suka sebelum diangkat. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '["Rahsia Lagi Sedap: Banyakkan bawang putih kerana ia memberi identiti rasa Mongolian.","Tambah 1 sudu besar mentega (unsalted butter) bersama sedikit minyak sebelum menumis bawang putih. Aroma jadi lebih kaya.","Gunakan lada hitam kisar kasar untuk rasa pedas berempah, bukan hanya pedas cili.","Jika ada, tambahkan 1 sudu besar crispy chili oil pada akhir masakan. Ia memberi rasa pedas, rangup dan aroma yang sangat sedap tanpa membuat nasi terlalu manis."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/nasi-goreng-daging-mongolian-style.webp', 'https://www.youtube.com/watch?v=x1KoqNA52TU', 2225, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/nasi-goreng-daging-mongolian-style.webp', 2225, 9.00, 'tier', 'pro', false
)
