-- Recipe Record: Crispy Rice Paper Roll (ID: 2226)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2226, 'Crispy Rice Paper Roll', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["100g cendawan shiitake segar/ayam/udang etc (hiris nipis)","biji kubis kecil, dihiris halus","batang lobak merah sederhana, dihiris halus memanjang (julienne)","1 inci halia, dicincang halus","2 ulas bawang putih, dicincang halus","3 batang daun bawang, dihiris halus","2 sudu kecil minyak bijan panggang","10 keping rice paper","Minyak masak secukupnya (untuk menumis dan menggoreng)"],"section":"Bahan"}]'::jsonb,
    '[{"items":["Panaskan sedikit minyak dalam kuali dengan api sederhana.","Tumis halia dan bawang putih sehingga naik bau.","Masukkan cendawan shiitake dan masak sehingga airnya hampir kering.","Tambahkan kubis, lobak merah dan daun bawang. Gaul rata.","Masukkan kicap cair dan minyak bijan. Kacau sehingga semua sayur sedikit layu tetapi masih rangup.","Angkat dan biarkan inti sejuk sepenuhnya.","Celup sekeping rice paper ke dalam air selama 2-3 saat sehingga lembut ATAU basahkan sehelai kain bersih atau tuala dapur, kemudian perah sehingga hanya lembap dan tidak menitis air.","Bentangkan kain lembap di atas permukaan kerja yang rata. Letakkan sekeping rice paper di atas kain lembap.","Lipat atau tutup rice paper dengan bahagian kain yang lembap supaya kedua-dua permukaannya terkena kelembapan.","Biarkan selama 20 saat, atau sehingga rice paper menjadi lembut, anjal dan mudah dilipat.","Buka kain perlahan-lahan, letakkan inti, kemudian gulung seperti popia.","Cara Menggoreng: Panaskan minyak untuk menggoreng dalam kuali.","Goreng menggunakan api sederhana.","Balikkan beberapa kali sehingga semua bahagian bertukar perang keemasan dan rangup.","Angkat dan toskan di atas rak atau tisu dapur sebelum dihidangkan. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '["Jangan biarkan terlalu lama kerana rice paper akan menjadi terlalu lembik dan mudah koyak.","Jika masih keras, biarkan beberapa saat lagi di bawah kain lembap. Elakkan menambah terlalu banyak air.","Kaedah kain lembap membantu melembutkan rice paper secara sekata tanpa menjadi terlalu basah, sekali gus menghasilkan gulungan yang lebih kemas dan mudah dikendalikan."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/crispy-rice-paper-roll.webp', 'https://www.youtube.com/watch?v=d9xfMA6QV-A', 2226, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/crispy-rice-paper-roll.webp', 2226, 9.00, 'tier', 'pro', false
)
