VALUES (
    2227, 'Dipping Sauce', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["15g kicap cair (1 sudu besar)","15g halal cuka beras / cuka putih (1 sudu besar)","15g air (1 sudu besar)","2g minyak bijan","2 sudu kecil minyak cili (ikut tahap kepedasan)","1 batang daun bawang, dihiris halus","1 sudu besar daun ketumbar, dicincang halus","(Pilihan) 1 ulas bawang putih, dicincang halus","(Pilihan) sudu kecil gula jika suka rasa sedikit seimbang"],"section":"Bahan"}]'::jsonb,
