INSERT INTO public.media_library (id, filename, hero_url, thumb_url, card_url, dominant_color, seo_schema, type) OVERRIDING SYSTEM VALUE 
VALUES (2228, 'spicy-japchae-glass-noodles.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/spicy-japchae-glass-noodles.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/spicy-japchae-glass-noodles.webp', 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/spicy-japchae-glass-noodles.webp', '#0A1517', 'Spicy Japchae (Glass noodles)', 'image')
