-- Recipe Record: Spicy Japchae (Glass noodles) (ID: 2228)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2228, 'Spicy Japchae (Glass noodles)', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["120-150g Korean glass noodles (dangmyeon)","250g daging lembu atau ayam (bahagian yang sedikit berlemak-hiris)","biji bawang holland (potong wedges)","4 biji cendawan shiitake (hiris)","50g lobak merah, hiris halus memanjang (julienne)","biji capsicum kuning, hiris memanjang","biji capsicum merah, hiris memanjang","50g kucai (garlic chives), potong sepanjang 5-6cm Atau Daun bawang","3 ulas bawang putih, cincang halus","1 sudu besar minyak masak","1 sudu besar minyak bijan","Bijan sangai secukupnya","sudu besar gochugaru (serbuk cili Korea)","1-2 sudu besar gochujang (pes cili Korea)","2 sudu besar gula","80ml air"],"section":"Bahan"}]'::jsonb,
    '[{"items":["1. Sediakan mi: Rendam mi kaca Korea di dalam air suam selama 30 minit sehingga lembut.","Jika mi terlalu panjang, gunting kepada panjang kira-kira 20cm supaya lebih mudah dimakan.","2. Sediakan Bahan: Hiris nipis daging atau ayam. Hiris bawang holland dan cendawan. Potong lobak merah secara julienne. Hiris capsicum memanjang. Potong kucai Cina sepanjang 5-6cm. Cincang halus bawang putih.","3. Sediakan Sos: Satukan semua bahan sos di dalam mangkuk dan kacau sehingga gula larut sepenuhnya.","4. Memasak: Panaskan minyak di dalam kuali atau wok menggunakan api sederhana tinggi.","Masukkan daging atau ayam dan tumis selama 3-4 minit sehingga bertukar keperangan. Jika menggunakan bahagian daging yang kurang berlemak, tambahkan 1-2 sudu besar minyak.","Masukkan bawang putih cincang dan tumis selama 30 saat hingga naik bau. Jika guna daun bawang boleh masukkan bahagian putih dan tumis seketika.","Masukkan bawang holland, lobak merah dan cendawan. Tumis selama 2 minit sehingga sayur mula lembut.","Masukkan mi yang telah ditoskan bersama sos. Gaul rata selama 3 minit sehingga mi menyerap sos dan kebanyakan kuah mengering. Jika mi masih keras, tambahkan sedikit air dan teruskan memasak sehingga lembut.","Perlahankan api. Masukkan capsicum dan kucai/daun bawang. Gaul selama 1 minit sahaja supaya sayur masih rangup.","Tutup api. Masukkan minyak bijan dan taburkan bijan sangai.","Rasa dan tambah garam jika perlu.","Hidangkan ketika masih panas dan taburkan sedikit lagi bijan sangai sebagai hiasan."],"section":"Cara Memasak"}]'::jsonb,
    '["Gunakan daging ribeye, short plate atau paha ayam tanpa tulang untuk hasil yang lebih lembut dan berjus.","Jangan terlebih masak capsicum dan kucai supaya kekal rangup serta warnanya lebih menarik."]'::jsonb,
    'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/spicy-japchae-glass-noodles.webp', '', 2228, 'https://kkfctwmrgvrinoythhqb.supabase.co/storage/v1/object/public/media/Recipes/vol22/spicy-japchae-glass-noodles.webp', 2228, 9.00, 'tier', 'pro', false
)
