-- Recipe Record: Gula Melaka Dalgona Coffee (ID: 2229)
INSERT INTO public.recipes (id, title, category, difficulty, time, author, volume, status, base_servings, rating, is_featured, tags, ingredients, steps, notes, image, video, cover_image_id, hero_image, hero_image_id, price, price_type, recipe_tier, is_free) OVERRIDING SYSTEM VALUE 
VALUES (
    2229, 'Gula Melaka Dalgona Coffee', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["40g gula Melaka","Sedikit air"],"section":"Gula Melaka Syrup"},{"items":["125ml susu suam","3 sudu kecil gula Melaka syrup"],"section":"Bancuhan Susu"},{"items":["2-3 sudu besar gula melaka syrup","1-2 sudu kecil serbuk kopi pilihan","2 sudu besar air panas","Ais secukupnya"],"section":"Gula Melaka Whip"}]'::jsonb,
    '[{"items":["Gula Melaka Syrup: Masukkan gula Melaka dan air ke dalam periuk.","Masak dengan api sederhana sehingga gula Melaka larut dan syrup menjadi sedikit pekat. Ketepikan dan biarkan sejuk.","Bancuhan Susu: Campurkan susu suam bersama gula Melaka syrup. Kacau sehingga sebati.","Gula Melaka Whip: Campurkan gula Melaka syrup yang telah sejuk bersama serbuk kopi dan air panas.","Whip sehingga menjadi gebu dan mencapai medium stiff peak. Ketepikan.","Penyediaan: Drizzle gula Melaka syrup pada bahagian dalam gelas.","Masukkan ais secukupnya.","Tuangkan bancuhan susu gula Melaka.","Letakkan gula Melaka whip di atasnya.","Sedia untuk dinikmati. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
