VALUES (
    2230, 'Kari Ikan Mudah', 'Mains', 'Intermediate', '30 min', 'Abid Nasa', 'VOL 22', 'published', 4, 4.9, false, '["vol 22","premium","mains"]'::jsonb,
    '[{"items":["1 ekor tenggiri/bawal/kembung (1-1.2kg), dipotong dan dibersihkan","cawan santan (jika suka)","10 tangkai bendi","2 biji tomato, dibelah 4","2-3 sudu besar air asam jawa (secukup rasa)","Sedikit air (untuk garingkan rempah)","1 biji bawang besar, dihiris nipis","3 ulas bawang putih, dihiris nipis","1 inci halia, di hiris nipis","4 tangkai daun kari","sudu kecil halba campur","1 mangkuk kecil minyak masak"],"section":"Bahan"},{"items":["5 biji bawang merah","3 ulas bawang putih"],"section":"Bahan Tumbuk"},{"items":["1 pek kecil rempah kari ikan (25g)","1 sudu besar serbuk cili"],"section":"Bancuhan Rempah"}]'::jsonb,
    '[{"items":["Hiris bawang, bawang putih dan halia ketepikan. Tumbuk bawang merah dan bawang putih hingga lumat.","Bancuhkan rempah kari ikan serbuk cili bersama cawan air hingga menjadi pes.","Panaskan minyak, kemudian tumiskan bawang besar, bawang putih, daun kari dan halba campur sehingga bawang lembut dan kekuningan.","Campurkan bahan tumbuk bersama bancuhan rempah kari, serbuk cili dan air. Tumis sehingga pecah minyak. Sepanjang proses ini, masukkan sedikit air supaya rempah masak sekata dan garing. Ulang 2-3 kali masukkan air.","Kemudian, tuangkan 2-2 cawan air dan biarkan mendidih.","Masukkan air asam jawa dan garam secukup rasa. Rasa dan sesuaikam dengan citarasa.","Masukkan potongan ikan tenggiri dan masak dengan api sederhana.","Masukkan bendi dan tomato, masak lagi 2-3 minit.","Tuangkan santan dan kacau perlahan. Biarkan kuah hampir mendidih, kemudian terus tutup api. Resting kuah sebelum di hidangkan. Siap."],"section":"Cara Memasak"}]'::jsonb,
    '[]'::jsonb,
